SELECT *
FROM user_address
WHERE delete_flag = 0

    AND create_user = #{createUser}


    AND receive_name LIKE CONCAT('%', #{receiveName}, '%')


    AND receive_phone = #{receivePhone}


    AND default_flag = #{defaultFlag}

ORDER BY default_flag DESC, create_time DESC

mapper.update:
UPDATE user_address
SET default_flag = 1, update_time = NOW()
WHERE id = #{addressId}
  AND create_user = #{userId}
  AND delete_flag = 0
